import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const url = 'file://' + process.argv[2];
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new','--remote-debugging-port=9333','--user-data-dir=/tmp/ps5cdp/prof','--window-size=1600,1100', url]);
const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws;
for (let i = 0; i < 40; i++) { try { const l = await (await fetch('http://127.0.0.1:9333/json')).json();
  const p = l.find(t => t.type === 'page'); if (p) { ws = new WebSocket(p.webSocketDebuggerUrl); break; } } catch {} await sleep(250); }
await new Promise(r => ws.onopen = r);
let id = 0; const pend = {}; const logs = [];
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pend[m.id]) { pend[m.id](m); delete pend[m.id]; }
  if (m.method === 'Runtime.consoleAPICalled' || m.method === 'Runtime.exceptionThrown') logs.push(JSON.stringify(m.params).slice(0, 300)); };
const send = (method, params = {}) => new Promise(r => { const i = ++id; pend[i] = r; ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async x => (await send('Runtime.evaluate', { expression: x, awaitPromise: true, returnByValue: true })).result.result.value;
await send('Runtime.enable'); await send('Page.enable'); await sleep(800);
// intercept downloads: capture blobs passed to anchors
await ev(`window.__dl=[]; const oc=URL.createObjectURL; URL.createObjectURL=function(b){window.__dl.push({type:b.type,size:b.size,blob:b}); return oc.call(URL,b)}; HTMLAnchorElement.prototype.click=function(){window.__dl[window.__dl.length-1].name=this.download}; 1`);
console.log('initial class:', await ev(`document.getElementById('drawing').getAttribute('class')`));
await ev(`document.getElementById('toggle').click(); 1`); await sleep(1500);
console.log('after toggle:', await ev(`document.getElementById('drawing').getAttribute('class') + ' aria=' + document.getElementById('toggle').getAttribute('aria-checked')`));
const shot = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync('/tmp/ps5cdp/page-asm.png', Buffer.from(shot.result.data, 'base64'));
await ev(`document.getElementById('dl-svg').click(); 1`);
await ev(`document.getElementById('dl-png').click(); 1`);
for (let i = 0; i < 40 && (await ev(`window.__dl.length`)) < 2; i++) await sleep(250);
console.log('downloads:', await ev(`JSON.stringify(window.__dl.map(d=>({name:d.name,type:d.type,size:d.size})))`));
console.log('status:', await ev(`document.getElementById('status').textContent`));
const png = await ev(`new Promise(r=>{const fr=new FileReader(); fr.onload=()=>r(fr.result); fr.readAsDataURL(window.__dl[1].blob)})`);
writeFileSync('/tmp/ps5cdp/export.png', Buffer.from(png.split(',')[1], 'base64'));
const svgTxt = await ev(`window.__dl[0].blob.text()`); writeFileSync('/tmp/ps5cdp/export.svg', svgTxt);
await ev(`document.getElementById('toggle').click(); 1`); await sleep(1500);
const shot2 = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync('/tmp/ps5cdp/page-exp.png', Buffer.from(shot2.result.data, 'base64'));
console.log('logs:', logs);
ws.close(); chrome.kill();
EOF
cd /tmp/ps5cdp && node test.mjs /private/var/folders/6g/0fzvn88n34q8hbxh7l32npfc0000gn/T/skillshed-demo-ps5-teardown-plain-7o7CBN/dist/index.html; file export.png; head -c 300 export.svg

